def parse_duration(s: str) -> int:
    if not s or not isinstance(s, str):
        raise ValueError(f"Invalid duration string: {s!r}")

    total = 0
    i = 0
    n = len(s)

    while i < n:
        # Read the number part
        start = i
        while i < n and s[i].isdigit():
            i += 1
        if i == start:
            raise ValueError(f"Missing number before unit in: {s!r}")
        num = int(s[start:i])

        # Read the unit part
        if i >= n:
            raise ValueError(f"Missing unit after number in: {s!r}")
        unit = s[i]
        i += 1

        if unit == 'h':
            total += num * 3600
        elif unit == 'm':
            total += num * 60
        elif unit == 's':
            total += num
        else:
            raise ValueError(f"Unknown unit '{unit}' in: {s!r}")

    return total
